import SwiftUI
import SentinelDomain

/// Turns one request into a reviewed pf change. The preview is generated by the
/// same planner that the app applies, so what the person reads here is the rule
/// that will be installed, not a friendlier description of it.
struct BlockEditor: View {
    @EnvironmentObject var model: SentinelModel
    @Environment(\.dismiss) private var dismiss

    @State private var address: String
    @State private var usePort: Bool
    @State private var portText: String
    @State private var transport: BlockTransport
    @State private var direction: BlockDirection
    @State private var note: String
    @State private var showRules = false
    @State private var attempted = false

    private let sourceEndpoint: String?

    init(target: BlockTarget) {
        _address = State(initialValue: target.address)
        _usePort = State(initialValue: target.port != nil)
        _portText = State(initialValue: target.port.map(String.init) ?? "")
        _transport = State(initialValue: target.transport)
        _direction = State(initialValue: target.direction)
        _note = State(initialValue: target.note ?? "")
        sourceEndpoint = target.sourceEndpoint
    }

    var body: some View {
        VStack(spacing: 0) {
            header
            Divider()
            ScrollView {
                VStack(alignment: .leading, spacing: 14) {
                    targetForm
                    preview
                    if let error = model.blockError, attempted {
                        errorBanner(error)
                    }
                }
                .padding(16)
            }
            Divider()
            footer
        }
        .frame(minWidth: 620, idealWidth: 700, minHeight: 520, idealHeight: 620)
        .onAppear {
            model.blockError = nil
            model.blockOutput = nil
        }
    }

    // MARK: - Header and footer

    private var header: some View {
        HStack(alignment: .top, spacing: 12) {
            Image(systemName: "hand.raised.fill")
                .font(.title2)
                .foregroundStyle(.red)
            VStack(alignment: .leading, spacing: 4) {
                Text("Block a network target")
                    .font(.title3.weight(.semibold))
                Text("This installs a rule in pf. It applies to this Mac, not to one app, and it is not a domain sinkhole.")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
            Spacer()
            Button {
                dismiss()
            } label: {
                Image(systemName: "xmark.circle.fill")
                    .font(.title3)
                    .foregroundStyle(.tertiary)
            }
            .buttonStyle(.plain)
            .help("Close without applying")
        }
        .padding(16)
    }

    private var footer: some View {
        HStack(spacing: 10) {
            if model.isApplyingBlock {
                ProgressView().controlSize(.small)
                Text("Waiting for administrator approval…")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            } else {
                Text("macOS will ask for an administrator password once.")
                    .font(.caption)
                    .foregroundStyle(.tertiary)
            }

            Spacer()

            Button("Cancel") { dismiss() }
                .keyboardShortcut(.cancelAction)

            Button {
                guard let target = candidate else { return }
                attempted = true
                Task {
                    let applied = await model.applyBlock(target: target)
                    if applied { dismiss() }
                }
            } label: {
                Label("Apply Block", systemImage: "hand.raised.fill")
            }
            .keyboardShortcut(.defaultAction)
            .disabled(!canApply)
        }
        .padding(12)
    }

    // MARK: - Form

    private var targetForm: some View {
        InspectorSection("Target", subtitle: "address or CIDR, optionally one port") {
            VStack(alignment: .leading, spacing: 10) {
                HStack(alignment: .firstTextBaseline, spacing: 8) {
                    Text("Address")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .frame(minWidth: 74, alignment: .leading)
                    TextField("203.0.113.9 or 203.0.113.0/24", text: $address)
                        .textFieldStyle(.roundedBorder)
                        .font(.system(.body, design: .monospaced))
                    if let sourceEndpoint {
                        Text("observed: \(sourceEndpoint)")
                            .font(.caption2)
                            .foregroundStyle(.tertiary)
                    }
                }

                HStack(alignment: .firstTextBaseline, spacing: 8) {
                    Text("Port")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .frame(minWidth: 74, alignment: .leading)
                    Toggle("Only this port", isOn: $usePort)
                        .toggleStyle(.checkbox)
                        .font(.caption)
                    TextField("443", text: $portText)
                        .textFieldStyle(.roundedBorder)
                        .font(.system(.body, design: .monospaced))
                        .frame(width: 90)
                        .disabled(!usePort)
                    if usePort {
                        Picker("Protocol", selection: $transport) {
                            ForEach([BlockTransport.tcp, .udp, .any], id: \.self) { item in
                                Text(item.label).tag(item)
                            }
                        }
                        .labelsHidden()
                        .frame(width: 130)
                    }
                    Spacer()
                    Text("Leave the port off to block every port.")
                        .font(.caption2)
                        .foregroundStyle(.tertiary)
                }

                HStack(alignment: .firstTextBaseline, spacing: 8) {
                    Text("Direction")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .frame(minWidth: 74, alignment: .leading)
                    Picker("Direction", selection: $direction) {
                        ForEach(BlockDirection.allCases) { item in
                            Text(item.label).tag(item)
                        }
                    }
                    .labelsHidden()
                    .frame(width: 170)
                    Spacer()
                }

                HStack(alignment: .firstTextBaseline, spacing: 8) {
                    Text("Note")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .frame(minWidth: 74, alignment: .leading)
                    TextField("Why this block exists (kept in the audit log)", text: $note)
                        .textFieldStyle(.roundedBorder)
                }
            }
        }
    }

    // MARK: - Preview

    @ViewBuilder
    private var preview: some View {
        if let plan {
            InspectorSection("Preview", subtitle: "the whole anchor after this change") {
                VStack(alignment: .leading, spacing: 8) {
                    ForEach(plan.targets) { target in
                        HStack(spacing: 6) {
                            Image(systemName: "circle.fill")
                                .font(.system(size: 5))
                                .foregroundStyle(.secondary)
                            Text(target.displayName)
                                .font(.system(.caption, design: .monospaced))
                            Text("\(target.direction.label) · \(target.port == nil ? "all protocols" : target.transport.label)")
                                .font(.caption2)
                                .foregroundStyle(.secondary)
                        }
                    }

                    if !plan.errors.isEmpty {
                        ForEach(plan.errors, id: \.self) { error in
                            Label(error, systemImage: "xmark.octagon")
                                .font(.caption)
                                .foregroundStyle(.red)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                    }

                    if !plan.warnings.isEmpty {
                        Divider()
                        ForEach(plan.warnings, id: \.self) { warning in
                            Label(warning, systemImage: "exclamationmark.triangle")
                                .font(.caption)
                                .foregroundStyle(.orange)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                    }

                    if plan.isValid, !plan.rules.isEmpty {
                        DisclosureGroup("pf rules that will be installed", isExpanded: $showRules) {
                            VStack(alignment: .leading, spacing: 3) {
                                ForEach(plan.rules) { rule in
                                    Text(rule.text)
                                        .font(.system(.caption2, design: .monospaced))
                                        .textSelection(.enabled)
                                        .fixedSize(horizontal: false, vertical: true)
                                }
                            }
                            .padding(.top, 6)
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }
                        .font(.caption)
                    }
                }
            }
        } else {
            InspectorSection("Preview") {
                Text(validationPrompt)
                    .font(.caption)
                    .foregroundStyle(.orange)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
    }

    private func errorBanner(_ text: String) -> some View {
        Label(text, systemImage: "exclamationmark.triangle.fill")
            .font(.caption)
            .foregroundStyle(.orange)
            .fixedSize(horizontal: false, vertical: true)
            .padding(10)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(Color.orange.opacity(0.1), in: RoundedRectangle(cornerRadius: 7))
    }

    // MARK: - Validation

    private var trimmedAddress: String {
        address.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private var parsedPort: UInt16? {
        UInt16(portText.trimmingCharacters(in: .whitespacesAndNewlines))
    }

    private var portIsValid: Bool {
        guard usePort else { return true }
        return (parsedPort ?? 0) > 0
    }

    private var candidate: BlockTarget? {
        guard !trimmedAddress.isEmpty, portIsValid else { return nil }
        return BlockTarget(
            address: trimmedAddress,
            port: usePort ? parsedPort : nil,
            transport: usePort ? transport : .any,
            direction: direction,
            note: note.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? nil : note,
            sourceEndpoint: sourceEndpoint
        )
    }

    private var plan: BlockPlan? {
        candidate.map { model.planBlock(adding: $0) }
    }

    private var canApply: Bool {
        plan?.isValid == true && !model.isApplyingBlock
    }

    private var validationPrompt: String {
        if trimmedAddress.isEmpty {
            return "Enter an IPv4 or IPv6 address, or a CIDR range."
        }
        if !portIsValid {
            return "The port must be a whole number between 1 and 65535."
        }
        return "The target could not be validated."
    }
}
